INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1209021-ics253', 'stk-zoroo', 'ICS 253', 'info', '{"desc": "الكورس عايدي لا هو بسهل ولا بصعب، وهو بعيد عن البرمجة حيث يركز على مبادئ المنطق…\n\nبالنسبة لشباب الكمبيوتر اذا اردتم الفهم أو القريد، فانصحكم بالحرص على التنزيل مع دكتور شريح لأن المادة يراها بعض الشباب لحسة، والحرص على الكتاب لأنه شامل كامل…\n\nواما اللي يبي يأخذها الكتف فما أدري، الكورس مهب كورس قريد، ولا راح تستفيد منه في استعمال الكمبيوتر، حيث ان الكورس اقرب للماث من الكمبيوتر ساينس…\n\nبالتوفيق، وإذا فيه اسئلة أنا حاضر\n\nتعديل:\nبالنسبة للصيف فمش عارف…\nنصيحة اخرى، ترا أصعب المادة اخرها فلا تتهاون فيها…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/6", "user": "zoroo", "ts": 1365722927000, "tid": 120840, "pn": 6}}', 1365722927000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1217985-ics253', 'stk-compuholic', 'ICS 253', 'info', '{"desc": "يا شباب الكورس أقرب ما يكون إلى الماث,كل أبوه منطق وإثباتات ومبدأ العد والاحتمالات\nبس الفائدة منه كيف تطبق دي الأشياء في حلول الكمبيوتر…\n\nطبعا تقسيم الدرجات فيه حسب علمي:\n15% هومووركات وكلاس وورك\n15% كويزات\n15% ميجر ون\n20% ميجر تو\n35% الفاينال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/10", "user": "Compuholic", "ts": 1367417633000, "tid": 120840, "pn": 10}}', 1367417633000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1334199-ics253', 'stk-vlesco', 'ICS 253', 'info', '{"desc": "شباب ذا الكورس لا هو بسهل ولا هو بصعب لكن من ناحية غثيث فهو غثيث\nبداية الكورس يتكلم عن المنطق واساسيات المنطق وبعدين يجي سكشن عن الاثباتات\nثم تدخل تشابتر عن sets ,functions and sequences and summation\nيأتي تشابتر بعده عن induction أو الاستقراء الرياضي ان كنتم تعرفونه مع اني عارف ان ما حولكم الا الدجه 😆\nويدخلك على تشابتر كله counting وكيف تحسب مثلا عدد الباسوردات المتكونة من 10 خانات والباسورد مثلا كله ارقام مافي حروف شيء زي كذا\nوبعدين يدخل على الاحتمالات وأغلب الامثلة على ذا التشابتر عن القمار 😂\nواخر تشابتر والله مدري وش هو اصلا لاني دخلت الفاينل وما ادري وش هرجته 😆\nلكن أتوقع كان related recursion أو شيء زي كذا وعلى حسب ما سمعت من الطلاب انه أصعب تشابتر خويكم في الله خلص الكورس ولا يعرف ماتيريال الفاينل 😞\nاخر شيء تذكروني بدعوة لي ولوالدي 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/14", "user": "vlesco", "ts": 1393360330000, "tid": 120840, "pn": 14}}', 1393360330000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1359279-ics253', 'stk-s2012055', 'ICS 253', 'info', '{"desc": "جودة المقرر بشكل عام\n\nأقرب للماث من البرمجة\n\nلكن كل هالنظيريات لها تطبيقات كثيرة في البرمجة الكمبيوتر\n\nالمواضيع التي يغطيها المقرر\n\nPropositional logic\n( اخذناها في الثانوي اللي صائبة وخاطئة واذا فان واذا واذا فقط)\nشابتر اذا تمكنت منه حبيته واذا ما تمكنت منه راح تضيع بسهولة يحتاج الى تدريب\n\nBasic Structers: sets, functions,…\n\nأسهل شابتر راح يمر عليك في الكورس\nبس انتبه من المتتابعات تقريبا هي أصعب شي\n\nInduction and Recursion\n\nبرضه ثاني سهل شابتر في الكورس بس خذ بالك من الRecursion جابو لنا سؤال عليه في الفاينل كان سلخ بمعنى الكلمة\n\nCounting and Discrete Probability\n\nشابتر سللللخ بكل ما تعنيه الكلمة, اتعب مع هذا الشابتر عشان تفهمه صح لأن الاسئلة تلحس من جد\nوأتذكر أيضا جاه عليه أكثر من سؤال في الفاينل كانو أصعب من اللي في الكتاب بمراحل\n\nِAdvanced counting techniques\n\nشابتر متوسط الصعوبة, حل الاسئلة اللي في الكتاب واحرص انك تفهم الكونست لأن الكونست حقه جدا سهل\nبس الاسئلة أحيانا تكون معقدة\n\nالكتاب المستخدم للمقرر\n\nممتاز جدا جدا بس تراه يحتوي بعض الاخطاء الاملائية\n\nالامثلة والتمارين شاملة ومتنوعة الصعوبة وطريقة الكتاب في شرح الكونست سهلة ومباشرة\n\nمدى فائدته\n\nأكثر شابتر استفدت منه هو شابتر 1 و 5 لأنه أساسي جدا في الرياضيات وفي الاثبات فاحرص على هالشابترين انك تكون فاهمها\n\nاضافات:\n\nالمادة هذي على انها ماث وليست برمجة الا ان فيها من التفكير المنطقي اللي موجود في كورسات الICS الشيء الكثير\n\nفاذا عاملتها على انك تحل وتفكر بطريقة منطقية راح ترتاح وتسهل عليك المادة\n\nاحرص على حل اسئلة الكتاب اللي تقدر عليها واللي تحس انها ممكن تجي\n\nالمنهج للاختبار النهائي هو الأصعب كما ذكرت والدليل أن افرجنا في الميجر الاول والثاني كان 74 و72\n\nبينما الفاينل كان افرجنا 61. شوف الفرق بين الافرجين وتعرف ان ماتيريال الفاينل حريقة فخذ بالك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/15", "user": "s2012055", "ts": 1398799261000, "tid": 120840, "pn": 15}}', 1398799261000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1453073-ics253', 'stk-krooom', 'ICS 253', 'info', '{"desc": "162 مع الاستاذ حسني المحتسب\n\nجودة المقرر بشكل عام : المحتوى يعتبر خفيف بالنسبة لكورس 3 ساعات لكن أظن المشكلة انه مواضيعه غير اعتيادية فبعض الناس ما تدخل مخهم\nالمواضيع التي يغطيها المقرر : ربع الكورس عن العبارات الشرطية وكيف تحولهم الى رموز وربعه اشياء معروفه مثل الدوال والمجموعات والمتتابعات ونص الباقي اشياء خفيفة يمكن اصعبها البرهان والاحتمالات\nالكتاب المستخدم للمقرر: الكتاب كان حلو لكن فيه معلومات زايدة بزيادة لكن اللي يحب الرياضيات راح يستمتع فيه\nالأسئلة والأمثلة المستخدمة في المقرر : في البداية الامثلة حلوة لكن بعدين تبدا تصير معقدة والاستاذ حسني عنده سلايدات مفيده وحاط فيها اهم الامثلة\nمدى فائدته في الناحية التطبيقية : أظن صعب انك تطبق اللي فهمته لكن في مواضيع مثل العد والاحتمالات و حقين الماث اظنه يفيدهم كثير\n\nا للي يبي ياخذه اليكتف شف kfupm resources اذا تحس انه دخل مخك نزله والا راح تتعقد شوية\n\nAssessment Tool Weight\nClasswork (includes homework, quizzes, activities … etc.) 30%\nMajor Exam 1 (Class time, Sunday March 6, 2016) 20%\nMajor Exam 2 (Class time, Tuesday April 26, 2016) 20%\nFinal Exam (7:00 PM Thursday May 12, 2016 – Comprehensive) 30%", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/18", "user": "Krooom", "ts": 1467472058000, "tid": 120840, "pn": 18}}', 1467472058000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1516407-ics253', 'stk-ahmelq', 'ICS 253', 'info', '{"desc": "ICS253 - Prof. Sabri Mahmoud - 172\nDiscrete mathematics\nالكتاب: Discrete Mathematics and Its Applications النسخة السابعة.\n\nالمحاضرة كانت مملة نوعاً (طريقة التدريس)، لكن المادة مهمة جداً كأساس لمواد مثل ICS353 خصوصاً في الاثباتات (proofs) (في ICS353 راح تستخدم الاثباتات كثير، مثلاً كيف تثبت أصحية خوارزمية ما)\nعن نفسي كنت أتحاشى الرياضيات قدر الإمكان، لكن هالمادة حببتني أكثر فيه بالرغم من صعوبتها.\n\nالمنهج\nLogic and Proofs\nSets, Functions, Sequences and Sums\nInduction and Recursion\nCounting\nDiscrete Probability\nAdvanced Counting Techniques", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253-discrete-structures-i/120840/20", "user": "ahmelq", "ts": 1571884913000, "tid": 120840, "pn": 20}}', 1571884913000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457407-ics253', 'stk-bo_rayan', 'ICS 253', 'info', '{"desc": "نعم المادة ماث ويبيلها متابعة وتمرين كثيييير\nاذكر الميجر الثاني كان اعلى واحد ٣٠/٦٠ او حولها\nوالفاينال برضو الافرج كذا\n\nانا في اغلب كورسات الماث جبت A لكن في هالكورس جبت B\n\nف المادة مو سهلة ابدا ولا هي خفيفة\nع الاقل لما اخذتها مع الدكتور عادل (العميد)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253/174621/2", "user": "Bo_Rayan", "ts": 1473517256000, "tid": 174621, "pn": 2}}', 1473517256000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p784955-ics253', 'stk-can_you_say', 'ICS 253', 'info', '{"desc": "انا نزلت لي 17 ساعة السمستر الجاي\nبس يوم جيت اشوف مواعيد الاختبار في 4 مواد قريبة من بعض\n\nاختبار ال ics253 في يوم ومن بكرة اختبار ال swe 205\nفهل المادتين يبغالهم شغل وفهم\nولا المادتين سهلات\nلاني ناوي احذف ال ics253\nعلشان اقدر الحق اذاكر الفاينلز ما اتوهق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics253-swe-205/102373/1", "user": "Can_you_say", "ts": 1297269369000, "tid": 102373, "pn": 1}}', 1297269369000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p786429-ics253', 'stk-newb', 'ICS 253', 'info', '{"desc": "> 205 سهله جدا ومادة قريد ، ومثل ما قال دحوم … مادة سواليف\n> حاول تسجل اسئلة الدكتور خالد عن المحاضره السابقه (يقولها اول خمس دقائق من كل محاضره)\n> ايضا يستحسن انك تلخص اللي غطيتوه نهاية كل اسبوع عشان اذا جاء الفاينل تكون مرتاح\n> 253 تتكون من سبعه فصول … +500 صفحه تقريبا\n> تحتاج منك متابعه وحل اسئله بكثرررره … واذا ما كنت من اللي يذاكرون اول باول (تحضير ومراجعه) فصدقني\n> راح تتعب فيها لان منهج الفاينل طوييييل.\n> اذا كنت عند صبري محمود …احرص على حل اسئلة الواجب لانه يجيب الكوزات منها تماما او\n> يجيب نفس الفكره\n\n> الله يوفقك 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics253-swe-205/102373/8", "user": "newb", "ts": 1297457586000, "tid": 102373, "pn": 8}}', 1297457586000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p741512-ics253', 'stk-everest', 'ICS 253', 'info', '{"desc": "Ics253\n\nانا اخد المادة الحين\nخلصنا من المادة شبترين\n\nالاول يتكلم عن طرق الاثبات: يبدا من الشروط البسيطة وبعدين الشروط المركبة وطرق الاثبات\nالشابتر الثاني اسهل يتكلم عن المجموعات وخصائصها والعمليات الي ممكن تسويها عليها واخر شي المتسلسلات (معظمه اخدنا في المدرسة)\n\nباقي المنهج يدخل في نظرية الاحتمالات ونظرية العد (التوافيق والتباديل) وفي رسم وفي شبتر عن Trees\nهاده الي اقدر اقوله الحين…\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-253/98967/2", "user": "EvErEst", "ts": 1291715977000, "tid": 98967, "pn": 2}}', 1291715977000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023067-ics253', 'stk-iiiii', 'ICS 253', 'info', '{"desc": "ics253 عبارة عن مادة ماث وتعتبر تكملة للـ boolean algebra في ee200 …\nphys215 مادة حفظ ويقولون سهله وفي ناس يقولون انهم صارو يعقدون الماده والقريدات صعبه فيها لكن يمكن هالكلآم نسبي …\nبعدين اي ماده تنزلها راح تدخل في المعدل إلآ إذا أخذتها مستمع … وأنا أشوف أنك تاخذ الماده الي تبيها أفضل …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124308/2", "user": "IIIII", "ts": 1334520810000, "tid": 124308, "pn": 2}}', 1334520810000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1257441-ics253', 'stk-user8985', 'ICS 253', 'info', '{"desc": "بنسبة ICS253 أنا أخذتها في الصيف 123\nالمادة من ناحيت المنهج جميلة ومتوسطة الصعوبة\n\nنصائح :\nالمواد الي منزلنها تحتاج حل مسائل بشكل كبير خصوصا\nICS253 و EE202\nEE200 تبدأ سهلة ثم تصعب تدريجيا فلا تستهين بها\nبحط ملفات حق ICS253 في KFUPM Resources\nحملهم راح يفيدوك كثيراً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/123-131/143027/88", "user": "user8985", "ts": 1377954250000, "tid": 143027, "pn": 88}}', 1377954250000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1291162-ics253', 'stk-e-asb', 'ICS 253', 'info', '{"desc": "مشكوورين على الاقتراحات والنصايح الطيبة 🌹 ❤️\n\nبالنسبة لمواد الالكتيف … كيف اعرف المتطلبات السابقة عشاان اقدر انزل الكورس … خشيت موقع الهندسة الكهربائية وما حصلت الا اسماء المواد …\nمثلا مادة ics 253 … روحت موقع علوم الحاسب وشوفت المخطط الشجري حقهم لقيت المتطلب الوحيد للمادة ics 102 …ز وزي ما انتوا عارفين احنا ناخد ics 103 فما ادري هل اقدر انزل المادة ولا لا\n\nويريت تقارنوا لي الكميستري مع الماث والفيزيكس من ناحية الكرف (بشكل عام) …(ما اتكلم عن صعوبة الاسئلة او طول المنهج) … يعني حسب الجهد المبذول والي ياخد وقت في المذاكرة اكتر … وكماان انقلش 102 و 101 … عشاان اقدر اتصور الوضع افضل بالمواد الي درستها … وكيف الريبورت ياخد جهد كبيرر … لاني لمن شفت سليبوس 102 شوفت ان متطلباتها اقل من 101 (لافي قرامر ولا فوكاب)بس انها زايده عنها بريبورت …\n\nوالله يعطيكم العافية 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/152404/6", "user": "e-asb", "ts": 1384967214000, "tid": 152404, "pn": 6}}', 1384967214000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p332715-ics253', 'stk-a.s.g', 'ICS 253', 'srcU', '{"html": "اسف بخصوص الرابط …<br>كان شغال يوم حطيته 😦<br><br>عموما الملفات حطيتها في المرفقات …🙂<br><br>بالتوفيق لك في دراستك …<br><br>​<span data-fid=\"stk-f332715-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f332715-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f332715-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f332715-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f332715-0": {"name": "ICS253-1.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/cc0c849fd924b34fc88a92e5823df19675b730c0e7a9a65528a4d0da4a581095"}, "stk-f332715-1": {"name": "ICS253-2.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e7f58c2b5d6b799276d9aed1d7494a77777afdd1ea2a75fd28f71f00b82f71d7"}, "stk-f332715-2": {"name": "ICS253-3.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d5a9922c635491a1c127c9a4575e90975ddda7fff1dee49674a6830d4b59896d"}, "stk-f332715-3": {"name": "ICS253-4.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/99103b254ecc4020637133e22092f4a8451b8a7a8b9d00dd165b84d5b2a24746"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics253/67773/5", "user": "A.S.G", "ts": 1226692123000, "tid": 67773, "pn": 5}}', 1226692123000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1472952-ics253', 'stk-user10429', 'ICS 253', 'srcU', '{"html": "قصدك ICS253 …<br>هذا syllabus عند الدكتور حسني المحتسب<br><br>​<span data-fid=\"stk-f1472952-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1472952-0": {"name": "ICS253 syllabus 161.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/af009e6d5c96e1f2e3adc34ffd5eb5aee4ec68af882ab022e51f8abeadea36c1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/course-syllabus-for-discreate-structures-i/176674/2", "user": "user10429", "ts": 1494448160000, "tid": 176674, "pn": 2}}', 1494448160000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p747194-ics253', 'stk-everest', 'ICS 253', 'srcU', '{"html": "تفضل<br><br>وهادي السلايدات الي اخدناها، لان السيلابس ما في الا اسامي الشابتر بس<br><br>Ics253<br><br>​<span data-fid=\"stk-f747194-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f747194-0": {"name": "101_ICS253-syllabus.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics/47733/229", "user": "EvErEst", "ts": 1292769775000, "tid": 47733, "pn": 229}}', 1292769775000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p482420-ics253', 'stk-user1269', 'ICS 253', 'srcU', '{"html": "هذه آخر نسخة … كانت موجودة في موقع رئيس القسم الدكتور عدنان قطب قبل فترة …<br><br>وأظنها آخر كوركلوم للقسم<br><br>عندك ics 252 يسير ics253 لانه مافيه 252 خلاص اني مور:)<br><br>وبالتوفيق اخوي 🌹🙂<br><br>​<span data-fid=\"stk-f482420-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f482420-0": {"name": "coe-studentguide-2006-2007.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/67b91286b395be9b9ed735494744079076b355b62fd2bb5b5f1c23dc4e6c1c77"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/curriculum/79413/4", "user": "user1269", "ts": 1256654509000, "tid": 79413, "pn": 4}}', 1256654509000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-krooom-ics253', 'stk-krooom', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98295", "n": "Dr. Husni Al-Muhtaseb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 ICS 253\n\nالتحضير : ورقة تمر ببداية الكلاس\nطريقة الشرح :من السلايدات وهي مختصرة جدا يعني يمكن ما تغطي نص الماتيريال و المادة يا تخش المخ او تعاني معاها و ترجع للكتاب (مثلي)\nالكويزات : كوزاته كثيرة واغلبها بعد الشرح يعني لازم تنتبه لشرحه\nالمياجر: 2 كلاس تيست الاول الافرج 73 والثاني 74\nالفاينلات :كان شي حار صراحة والافرج كان 54\nالقريد النهائي: ب+\nالصوت:واضح\nإضافات : احيانا يعطينا معلومات خارج الدرس ويحفز الطلاب على العلم و براءة الاختراع (هذا اكثر شي عجبني فيه) ولكنه غير متمكن بالمادة واغلب الطلاب يواجهون صعوبة فيها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452269-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husni-al-muhtaseb/98295/12", "user": "Krooom", "ts": 1466268940000, "tid": 98295, "pn": 12}}]}', 1466268940000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10429-ics253', 'stk-user10429', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98295", "n": "Dr. Husni Al-Muhtaseb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "161 ICS 253\n\nالتحضير : ينادي الأسماء بداية الكلاس وبعض الأحيان يمرر ورقة مكتوب فيها عدد غياباتك وتحضر نفسك فيها , ومتساهل في التأخير .\n\nطريقة الشرح : سلايداته ممتازة جداً لكن المادة طويلة وفيها دروس واجد والكلاس ساعة وربع فمضطر أنه مايتأخر في شرحه حتى يغطي المنهج ومايمل الطالب لكن إذا ركزت معه أمورك في السليم .\n\nالكويزات : دايماً يسأل الطلاب عن الطريقة اللي يبون يختبرون فيها الكويزات وهو يرفض يسميهم كويز, عادي يحل مسألة ثم يختبرنا عليها في نفس الكلاس … لكن مرة اختبرنا كويز كان عن 4 كويزات وكان بصعوبة الميجر تقريباً لكن وقت أقل .\nالمياجر: يرسل مثال لها في البلاك بورد وفي الغالب يكون الميجر نفس الطريقة بالضبط , بالنسبة لي أسهل بكثير من الاولد اكزامز\nالقريد النهائي: أ\nالصوت:واضح جداً\nإضافات : الدكتور متساعد جداً وإن كان يدقق بعض الأحيان على أشياء غريبة لكن هذا ماراح يغير تقييمه , مثل أنه يتوعد الطالب اللي يحك شعره أو لحيته بأنه يخصم عليه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1468294-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husni-al-muhtaseb/98295/13", "user": "user10429", "ts": 1487088877000, "tid": 98295, "pn": 13}}]}', 1487088877000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12093-ics253', 'stk-user12093', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98295", "n": "Dr. Husni Al-Muhtaseb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 253 - Term 212\n\nالتحضير: يوميا بعد تقريبا أول 10 دقائق عبر تكليف أحد الطلاب بأخذ التحضير، ويعطي تأخير.\n\nطريقة الشرح: يشرح سلايداته، والتي قد تكون أفضل سلايدات للمادة، شرحه عادي، عبارة عن قراءة السلايدات مع التفصيل عند ما يُحتاج لمزيد شرح وتوقف حال عدم فهم الطلاب.\n\nالكويزات: اختبرنا 6 كويزات طوال الترم، واحد منها كان إعادة لأحد الكويزات؛ لكون الأفرج متدني، مستواها سهل إلى متوسط، وغالبها تكون من أسئلة الكتاب.\n\nالمياجر: اختبار نصفي(Midterm Exam) مشترك.\n\nالفاينلات: مشترك.\n\nالقريد النهائي: B+.\n\nالصوت: واضح.\n\nإضافات: عليه شطحات بعض الأحيان لكن لا تؤثر في كونه جيّد. أعتقد أنّ شرح أي دكتور كائنا من كان في خصوص هذي المادة ليس بكبير أهميّة؛ لإمكان قراءة السلايدات وفهمها غالبا لوحدك أو عبر الرجوع للكتاب، وهو ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534516-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husni-al-muhtaseb/98295/17", "user": "user12093", "ts": 1653910684000, "tid": 98295, "pn": 17}}]}', 1653910684000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohmad_az-ics253', 'stk-mohmad_az', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "والحمد لله عدا الترم على خير والحين بعطيكم العلم عن الرجال\n\nالدكتور وصفي دكتور محترم واخلاق وتعامله مع الطلاب خيالي\n\nيعني A+ نهطيه من ناحية اخلاقه وتعامله مع الطلاب\n\nبالنسبه للتحضير تقريبا ٩٠ بالميه يحضر وغالبا ما يكون التحضير عن طريق بوب كويز\n\nالشرح اعطيه من B الى B+\n\nتصحيحه وما ادراك ما التصحيح\nعلى قولت واحد من الشباب \" الدكتور وصفي تقل كومبايلر \" ما شاء الله\n\nيعشق شي اسمه (ماينص ) خصم\n\nعن نفسي الصراحه كنت متحطم بشكل كبير بعد كل ميجر لما اشوف من سؤال واحد (-٩) 😦\n\nبس بالاخير اذا كانت مادتهافرج نزل عنده لانه مهما خصم بالاخير افرج\n\nيعني انا نزلت الصيف ١١٣ معاه ics253 والافرج النهائي ٦٤.3\n\nبالاخير اذا كان الكورس افرج ولا عندك دكتور معين براسك سجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1075511-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/13", "user": "mohmad_az", "ts": 1344049654000, "tid": 98306, "pn": 13}}]}', 1344049654000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-modywahab-ics253', 'stk-modywahab', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "153- ICS253\n161-ICS254\n\nالتحضير :\nيحضر عن طريق أكتيفتيز يعطيها نهاية الكلاس، وإذا مافيه أكتيفيتي يحضر بالاسماء، بس غالباً إذا ما فيه أكتيفيتي يسحب على التحضير. الأكتيفي تكون سهلة ومن نفس الدرس إلي يعطيه في المحاضرة.\n\nطريقة الشرح :\nطريقة شرحه برأيي جذابة جداً وحبيب ويضحك مع الطلاب، ويوصل المتريال بشكل مثالي، ويتجاوب مع السئلة وما يسحب عليها أبدا، ويحب يناقش الطلاب كثير.\n\nالكويزات :\nيعطي من ٥ إلى ٦ كويزات وياخذ أفضل ٤ منها. تكون غالباً من متوسطة إلى سهله، نفس أسئلة الكتاب بالضبط(إذا كان يدرس ديسكريت ماث)، وعنده أولد إقزامز خاصة فيه غالبا يجيب منها.\n\nالميجر الأول:\nكان متوسط، الافرج كان ٧٠٪، الأسئلة مشابهة للي بالكتاب والاولد إقزام.\n\nالميجر الثاني:\nكان في كل المادتين إلي أخذتهم معه صعب، لكن في ICS253 كان صعب لدرجة إستثنائية، الأفرج كان ٤٧٪، لكن الدكتور سوى حركة جبارة ما أتوقع قد سمعت عن دكتور سوى زيه. قرر إن الميجر بدال ما هو من ١٠٠ راح يكون من ٩٠ ، يعني الكان جايب في الميجر ٧٠٪، صار ٧٨٪. وإلي جاب فوق ال٩٠ عطاه فل والدرجات الباقية خلاها له بونس\n\nالفاينلات :\nنفس الميجر الاول كان متوسط الصعوبة، كان كومبريهنسف، المتريال حق الميجرين عليهم ٣٠٪ ملتبل تشويس ،٧٠٪ بالقية من المتريال الاخير\n\nالقريد النهائي:\nA+++\n\nالصوت:\nواضح .\n\nإضافات :\nالدكتور هذا بكل بساطة من النعم إلي أرسلها الله سبحانه وتعلى على قسمنا، زي ما ذكرت سابقاً الدكتور حبيب وذو أخلاق ومتسامح وبنفس الوقت شريح وإنسان فاهم في تخصصه. قبل فترة كنت جاي من سفر مواصل بيوم الدوام وأرسلت له إيميل عن وضعي وقالي توكل مب لازم تحضر الكويز، وضرب لي درجة كويز الي بعده بإثنين!\nوطبعاً أذا كنت تدور على دكتور يوزع درجات فإبعد عنه بالتأكيد، لكن ICS 253/254 ما يدرسها أحد بهالمواصفات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1464900-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/17", "user": "modywahab", "ts": 1482253036000, "tid": 98306, "pn": 17}}]}', 1482253036000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-ics253', 'stk-breaktheunbreakable', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور وصفي الخطيب\nICS 253 - 182\n\nبنود التقييم :\n\nالتحضير :\nيحضر قبل نهاية الكلاس، بعد كم أسبوع وقف تحضير.\nطريقة الشرح :\nيستعمل سلايداته ويجاوب كل أسئلة الطلاب. شرحه جيد، ليس سيئ أو ممتاز.\nالكويزات :\nتصحيح الدكتور في الكويزات ما يعجبني، لأنه بعض الأسئلة ما تكون واضحة متطلباتها. الكويزات مستواها متوسط الصعوبة تشبه المياجر\nالمياجر:\nبنظري سهلة، بس الوقت يغدر فيك. أفرج المياجر كان 60.\nالفاينلات :\nالفاينل كان صعب وأفرجه 55.\nالقريد النهائي:\nأعطي الدكتور B+. حصلت عنده A، مع أني كنت متوقع A+\nالصوت:\nمفهوم وواضح.\nإضافات :\n1- الواجبات ناخذها بالقطارة، انتهى السمستر وباقي 3 واجبات ما تصلحت إلا آخر يوم.\n2- ما نعرف شيء عن توزيع الدرجات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510175-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/21", "user": "BreakTheUnbreakable", "ts": 1558773060000, "tid": 98306, "pn": 21}}]}', 1558773060000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-ics253', 'stk-salman_al-ghamdi', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS253-191\nابو الوصف ما يحتاج اي تعريف، الرجل سمعته سابقته، انا جاي أأكد على ذا الشي.\n\nالتحضير : كل كلاس باستعمال إما الاكتيفيتي او التحضير العادي.\nطريقة الشرح : يشرح من سلايداته الخاصة ويكتب عليها طول الشرح باستعمال الايباد حقه… يمر على اللي تحتاج تفهمه ومستعد يعيده مرتين وثلاث لين ما تفهم… الدكتور عنده طريقة عجيبة في توصيل المعلومة وتوصل لك اغلب الاحيان.\nالكويزات : متوسطة مائلة للصعوبة، الدكتور يطحن طحن في ذا الشي.\nالمياجر: متوسطة لسهلة. مشتركة بينه وبين الدكتور عماد.\nالفاينلات : كومون … لكنه كان سهل والحمد لله والتصحيح ما قصر فينا.\nالقريد النهائي: A~A+\nالصوت: واضح جدا مع انه خفيف.\nإضافات : الدكتور قمة في الاخلاق والتعامل، بشوش ومرح وخفيف دم. برضو القريدات عنده صحيح انها على الافرج لكنها كانت حلوة صراحة. الواجبات** ط و ي ل ة** وفيها مليون سؤال والترم فيه مليون واجب والتسليم على ديدلاين معين بعده الله يستر عليك… بس كانت مفيدة صراحة وتغطي كل شيء. لو حصل لي فرصة انزل 353 عنده فبنزلها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518717-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/23", "user": "Salman_Al-Ghamdi", "ts": 1578150023000, "tid": 98306, "pn": 23}}]}', 1578150023000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics253', 'stk-mohammed_mag', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 253 - TERM 212 حضوري\n\nالتحضير :\nيحضر اخر الكلاس عن طريق اسامي او يعطيك اكتفتي تسلمه بموقع Grade scope يبين فيه اسمك, ومتسامح مع الميك اب علشان صارت لخبطه تغيير مباني وقتها.\n\nطريقة الشرح : جدا واضحه وممتازه, اغلب شرحه حل امثله بشكل واضح ويحب الاساله.\n\nالكويزات :\n6 متوسطه الصعوبه\n\nالميد : متوسط\n\nالفاينلات : صعب\n\nالقريد النهائي: +B\n\nالصوت: جدا ممتاز\n\nإضافات : الدكتور مسجل في الترم حقنا كل المحاضرات على اليوتيوب, بيكون مصدر جدا ممتاز للأترم الجايه لكم أستفيدو منها .\nبس نصيحه لا تاخذونها وتسحبون على الكلاسات لأن هالشيء نزل درجتي بشكل كبير.\nوأيضا الاكتفتي بتكون كثيره اتوقع حول ال 15 وبتتعب شوي وتاخذ وقت من الكلاس القادم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534499-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/26", "user": "Mohammed_Mag", "ts": 1653828527000, "tid": 98306, "pn": 26}}]}', 1653828527000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-ics253', 'stk-tryagain', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98308", "n": "Dr. S Al-Muhammadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 253 - Term 162\nالدكتور سلطان المحمدي\n\nقبل ما ابدأ … المادة هذي غثيثة وصعبة إلى حد ما وتحتاج دكتور يكون فاهم ويفهم صح … مو أي دكتور ينفع يدرسها\n\nالتحضير :\nكل كلاس يحضر على التابلت … في البداية ما كان يهتم للتأخير لكن بعدين صار يسجل المتأخرين.\n\nطريقة الشرح :\nالشرح يكون من التابلت ويكون موصل في البروجكتر … والشرح مو مميز بشكل كبير لأنه يعيد أمثلة الكتاب وأقل ما يقال عن الشرح بأنه عااادي. وبعدين لو عندك سؤال او استفسار وشافك مافهمت يسألك السؤال الاسطوري \" عندك PARTNER \" لأنه هو كل حصة يخليك تحل الاسئلة اللي يحطها على البروجكتر مع صاحبك اللي جنبك … فإذا ما فهمت يقلك إسأل صاحبك ولو صاحبك مو فاهم يقلك إسأل فلان الفلاني وهو رح يجاوبك ويكمل شرح … اسلوب مستفز شوي وما عجبني ابداً.\n\nالكويزات :\nغير إنها صعبة لكن هذا الترم انضغطنا فيه وعطانا 3 كويزات واخر كويز كان في اخر يوم في الترم وما حذف ولا كويز … والكويزات عليها 10 بالمية فكل كويز كان عليه 3.3 تقريباً من 100 … فلو خبصت بواحد راحت عليك …\n\nالمياجر:\nالميجر الاول كان متوسط إلى حد ما والدليل إنو في ناس جابت أعلى من 90 اتوقع 4 أو 5 مني متأكد … لكن المصيبة في التصحيح … تصحيح الدكتور سيء جداً جداً ونظامه لو جاوبت غلط على السؤال خلاص مالك حق إنك تناقشه في الـ partial credit اللي من الممكن يعطيك ياها … بمعنى آخر في سؤال إجابتك النهائية خطأ وعليه 5 درجات … وعطاك فرضاً 2 … مالك حق إنك تناقشه وتقله ليش ما عطيتني 3 او 4 لأنك بكل بساطة جاوبته غلط … وأسئلة الدكتور قليلة والسؤال الواحد يكون عليه درجات كثير.\nالميجر الثاني أعلى واحد جاب 84 والافرج كان 65 تقريباً … الميجر كمان كان متوسط مو صعب للأمانة لكن المصيبة في التصحيح فقط … التنقيص عنده من درجتين وانت طالع. ولو في سؤال يتطلب منك اجابة مبدئية بعدين شرح … يعني فرضاً صح أو خطأ مع الشرح … لو كتبت “صح” مع الشرح والاجابة خطاً اساساً ما يناظر في الشرح اللي شرحته … يعطيك صفر عالسريع.\n\nالفاينلات :\nالفاينال كمان كان متوسط مو صعب لكن المشكلة إنو في كثير من الافكار اللي يجيبها في المياجر او الفاينال ما يكون شارحها مزبوط فتلحس لكن بعدين لما تفهمها تكتشف إنها سهلة.\n\nالقريد النهائي:\nD\n\nالصوت:\nمرتفع ويوصل ويتكلم انجليزي وعربي.\n\nإضافات :\n- الدكتور ما يحب اللي يجلس على الجوال\n- الدكتور تصحيحه سيء\n- الدكتور شرحه سيء\n- الدكتور ما يعطيك درجات الفاينال وما ينزلها على البلاكبورد وما ينزل الـ final grade إلا آخر يوم اللي مطلوب من الدكاترة يسلمو فيه القريدات مدري يمكن عشان ما أحد يراجعه.\n- الدكتور يوهمك بأنه في مراجعة بعد تصحيح المياجر عشان ممكن يزيدك ويقلك إكتبلي جنب السؤال اللي حابب إني اراجعه ReGrade. لكن في الحقيقة تروح عنده وبطلوع الروح تطلع عنده بدرجة والمشكلة إنو ما يعدل درجتك على البلاكبورد مدري هل هو فعلاً عدلها ولا تركها زي ما هي.\n- الدكتور ما يجاوب على اسئلة الطلاب.\n- الدكتور في نهاية الترم ضغطنا ضغط مو طبيعي بسبب إنو غاب تقريباً أسبوعين بعد الميجر الثاني وخلانا نداوم آخر يوم خميس وكان عندنا الجمعة الصباح فاينال … وعشان يضمن إنك ما تغيب حط فيه كويز عليه 3 بالمية … وبكل بساطة إذا منت حاب تجي لا تجي. ورح تاخذ صفر.\n- الواجبات وما أدراك ما الواجبات … هذي قصة لوحدها…\nالواجبات يعطيك 6 واجبات وفي واجب سابع بونص اذا حابب تعوض عن واجب درجته سيئة …\nالواجب أولا صعب وفي كثير من الأحيان ما يكون بمستوى الشرح بتاتاً … وغير كذا تحل الواجب بساعتين وتكتبه بساعتين لأن الدكتور كان طالب من الكل إنو يحلو على برنامج او موقع الـ Latex وما يرضى الا فيه ( أو بالأحرى عشان ما اظلمه مافي أحد جرب إنو يسلمه على الوورد مثلا أو بخط يده فما ادري لكن اتوقع ما يرضى 🙂 ) والمشكلة الكتابة في الموقع صعبة والواجب بدل ما ياخذ ساعة مثلاً او ساعتين اللي هي مدة حله … زيد عليها ساعتين مدة كتابته … وعليه طريقة معقدة في الكتابة لأنو لازم تشترك مع طالب ثاني في كتابة الواجب ولازم إنت وياه تحلو مع بعض وطريقة طويلة ومعقدة ومالها أي داعي … بس عشان يبان إنك منظم وانت اساساً مو فاضي… وزيد عليها إنو رسم الـ Venn diagrams صعبة والتعامل مع الـ latex معقد.\n- اخيراً الدكتور سيء جداً جداً ولا انصح فيه بتاتاً ولو مافي غيره منزل الكورس ومنت مضطر إنك تنزل الكورس لا تاخذ عنده أبداً.\nوالمادة كانت من اسوا المواد اللي اخذتها الى الان بسبب واحد بس هو الدكتور. اللي فعلاً مثل ما ذكر بعض الشباب … تعقيد الطالب عنده شي مقدس.\n\nاتمنى ما اكون طولت عليكن لكن هذا الـ feedback اتوقع كافي ووافي للي حاب ياخد فكرة كاملة عن الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474768-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-muhammadi/98308/13", "user": "TryAgain", "ts": 1496933519000, "tid": 98308, "pn": 13}}]}', 1496933519000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-computist-ics253', 'stk-computist', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f98309", "n": "Dr. Nasir Darwish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 133 - SUMMER 2014\nICS253 - Descrete Mathematics (Structures)p\n\nالتحضير : يوميا أحيانا في بداية الحصة وأحيانا في نهايتها. يحاسب على التأخير وأحيانا ما تدخل\n\nطريقة الشرح : يستخدم سلايدات http://faculty.kfupm.edu.sa/ics/darwish/ICS253-Summer2014/ ويستخدم السبورة للأمثلة، أحيانا في السلايدات يضع بعض التساؤلات بدون إجابة وذلك مساحة للتفكير. إضافة إلى السلايدات في كثير من الأمثلة المحلولة PDF\n\nPPT http://faculty.kfupm.edu.sa/ics/darwish/ICS253-Summer2014/Slides/PropLogic-1.pps\nPDF http://highered.mcgraw-hill.com/sites/dl/free/0072880082/299355/ExtraExamples_1_2.pdf\n\nالكويزات : سهلة إلى متوسطة الصعوبة. عطانا ثلاثة كوزات + takehome\n\nالمياجر: متوسطة السهولة وتقدر تحصل درجة كاملة، الأفرج تقريبا 13 من 20\n\nالفاينلات : أقرب للصعوبة بالنسبة لي (ما ذاكرت عدة لأسباب عديدة منها السمر نفسه)\n\nالصوت: واضح ولكن أحيانا يتكلم بسرعة فينخفض صوته بس راح تغنيك السلايدات\n\nالدكتور هذا شفت تقييمه ما حصلت إلا لذم والتنكيل في المنتدى فأجلت آخذ الكورس أكثر من مرة حوالى سنة كاملة. قال لي بعض الشباب الي أخذوها معه إنه من أسوأ المدرسين وذكروا لي بعض السلبيات عنه - ربما أخلاقية - الي فعلا وجدتها فيه لكنها ليست مشكلة كبيرة. خصوصا إنه مدرس مرتب وكل شيء واضح وعندك خطة دراسية واضحة. هالدكتور مو من الأشخاص الي يمشوا بعض حركات الشباب من التأخير أو تحظر بجسمك في الحصة وأصلا أنت توتسب. أقدر أقول المدرس جدي ولكن ينكت أحيانا نكت علمية مثلا: two is the odd prime among odds، أو غيرها. لاحظت التفاعل مع الدكتور منخفض (4 طلاب من ~20). ربما أنا أشوف اسلوبه في الشرح تنويم مغناطيسي - كما يقول بعض الأشخاص - وأرجع السبب أنه عادة يتكلم في قضية ويتوسع في الكلام عنها وأنا أشوفها غير ذات أهمية عشان أنفق عليها من أهتمامي. لاحظت في يحب الجمع بين الحل الرياضي والحل البرمجي فكان يعطي بونص علي الي يكتب برنامج.\n\nالقريد النهائي: B+ - B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1392111-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-nasir-darwish/98309/32", "user": "Computist", "ts": 1408712161000, "tid": 98309, "pn": 32}}]}', 1408712161000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdu1002-ics253', 'stk-abdu1002', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f99591", "n": "Dr. Sabri A. Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يومي في بداية المحاضرة على ما أذكر\nطريقة الشرح : من السلايدات ويحل بعض المسائل على السبورة\n\nصراحة اضطررت إلى حذف المادة لأني لم أستطع إستيعابها بشكل جيد وفي ذلك جزء من تقصيري بالإضافة إلى أن شرح الأستاذ ليس جيدا… وقد تحاورت مع عدد من الزملاء الذين كانوا معي في مادته ics 253 ووجدت أنهم يشاطروني الرأي حوله…\nصوته كان لي واضحا مع بعض الخفوت…\nالقريد النهائي :c+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779822-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sabri-a-mahmoud/99591/2", "user": "Abdu1002", "ts": 1296505671000, "tid": 99591, "pn": 2}}]}', 1296505671000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-everest-ics253', 'stk-everest', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f99591", "n": "Dr. Sabri A. Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics253\nTerm: 101\n\nالتحضير: ورقة تمر على الطلاب وادا شاف الغياب كثير ينادي بالاسماء.\n\nطريقة الشرح: من سلايدات ويحل امثلة على السبورة. أكثر مايعيب هالمدرس هو طريقة شرحه…يعني يدخل في الدرس بدون مقدمات…والتعاريف والمصطلاحات يمر عليها مرور سريع الشي اللي يخلي الطالب ما يدري ويش صاير لما يوصل للأمثلة.\n\nالكويزات: متوسطة وساعات يجيك سؤال يبغا له شغل. المشكلة انهم ثلاثةوكل واحد عليه 4% يعني لازم تضبط أمورك فيها.\n\nالمياجر: نفس مستوى الكوزيزات بس لازم تذاكر وتحل مسائل والا بصير الاختبار ما ينحل بالنسبة لك. طبعا كل ميجر كان على شبتر واحد بس، وفي التصحيح يعطيك المدرس اكثر من حقك ويحاول يطلع لك بويتنس من اي مكان.\n\nالفاينلات: نفس كلام المياجر بس ماتيريل الفاينل اطول بكثييييييييير ويحتاج وقت. ومع اني ما شفت ورقتي بس متأكد اني اخدت اكثر من حقي.\n\nالصوت: منخفض وعلى مستوى واحد…تحتاج جهد عشان ما تسرح.\n\nإضافات: زي ما قلت المدرس شرحه لك عليه يعني احسب حسابك انك بتعتمد على نفسك شوي. بس اللي يعوضك ان لو تسأل الف مرة ما عنده مشكلة ويعيد المسالة مرة ومرتين ويسأل ادا تحتاج إعادة بعد.\n\nبشكل عام المدرس اخلاق ومتعاون ويدف بس مو حق شرح.\n\nالقريد النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p780730-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sabri-a-mahmoud/99591/3", "user": "EvErEst", "ts": 1296672032000, "tid": 99591, "pn": 3}}]}', 1296672032000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2012055-ics253', 'stk-s2012055', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f118617", "n": "Dr. Abdul Aziz M. Al-Khoraidly", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics 253, ics 254\n\nالتحضير :\n\nينادي بالاسماء آاخر خمس دقايق\n\nطريقة الشرح :\n\nيشرح على السبورة من نوت\n\nشرحه خووورافي ما شاء الله عليه الله معطيه قدرة في توصيل المعلومة بشكل سهل جدا\n\nالكويزات :\n\nمتوسطة الصعوبة\n\nالمياجر:\n\nنفس الكوزات وفيها فكرة او فكرتين جدد\n\nالقريد النهائي:\n\n+a وبجدارة\n\nالصوت:\n\nيصارخ ما شاء الله مستحيل تنام عنده\n\nإضافات :\n\nلا يفوتك\n\nنكتي وخفيف دم\n\nوحريص انك تطلع فاهم حتى لو يشرح مرة مرتين الى ان تفهم\n\nيا لبى قلبك يا عزوووز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1358473-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-al-khoraidly-abdul-aziz-m/118617/8", "user": "s2012055", "ts": 1398626795000, "tid": 118617, "pn": 8}}]}', 1398626795000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman97-ics253', 'stk-abdulrahman97', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f118623", "n": "Dr. Adel Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS-253\n\nالتحضير : يبدأ الكلاس بسوالف خفيفة بعدين يبدأ تحضير\n\nطريقة الشرح : يشرح من السلايدز واحيانا يعطينا امثلة من الكتاب اذا شاف اننا ما فهمنا بس بشكل عام شرحه ممتاز\n\nالكويزات : عطانا كويزات وورقية وبعضها بالبلاكبورد و مستواها متوسط\n\nالمياجر: ميجرين وما كانوا صعبين ابدا ويغطون اسئلة كثيرة فكانوا طويلين شوي\nبعض الاسئلة كانت يا صح يا خطأ يعني تاخذ 0 او مثلا 5 بس تصحيحه ما كان سيئ ابدا كان عادل الصراحة\n\nالفاينلات : فاينل يغطي المتيريال كامل ونفس نظام المياجر تقريبا\n\nالقريد النهائي: A++\n\nالصوت: ممتاز وواضح والاكسنت خرافي\n\nإضافات : بالبداية كنت متخوف الصراحة بعد ما شفت تقييمه هنا لكن طلع من افضل الدكاترة اللي مروا علي\nيعجبني فيه انه يلطف الجو احيانا بالكلاس بما ان الكلاس كان طويل ودائما بشوش و نشيط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504747-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-ahmed/118623/21", "user": "Abdulrahman97", "ts": 1547043320000, "tid": 118623, "pn": 21}}]}', 1547043320000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ics253', 'stk-guest', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f118623", "n": "Dr. Adel Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS253 - Term 201 - ثاني ترم لكورونا\nالكلاسات كلها اونلاين\n\nالتحضير : بداية الترم كان يحضر عن طريق فورم بتيمز يحط فيه سؤال من الدرس بعدها صار يسال سؤال مفاجئ للطلاب يشوف هم معه ولا لا .\n\nالشرح : شرحه وسط اقرب ل سيئ , ويشرح من الكتاب وما عنده سلايدات تسهل الموضوع شوي\n\nالكويزات : هنا نبدا نتكلم , ما اختبرنا ولا كويز قبل الميجر داخلين الميجر بعد فترة حذف المواد ولا اخذنا ولا كويز , بعدها حط لنا ٣ كويزات بفترات متقاربه بعد الميجر بالبلاك بورد ومليانه مشاكل لبكره , كلمته على ذي المشاكل وعدلها لي بس مدري عن غيري\n\nالمياجر : الميجر كان سهل للي مذاكر بسس (( تصحيحه مش ولابد )) يخسف فيك على ادنى شي يعطيك صفر على طول في بعض الاسئله عشان غلط بسيييييط .\n\nالفاينل : (خيارات بالبلاكبورد) الفاينل كان عن تقريبا ٣ تشابترز لان كان يشوفنا متمكنين من اللي قبل , الفاينل ٢٤ مدري ٢٣ , حرفيا نصه على جزئيه معينه من درس معين , نفس السؤال بالضبط بنفس الارقام لكن يغير الخيارات بمعنى لو ما ما فهمت ذيك الجزئيه راحت عليك , واذا ذاكرتها وتركت الباقي ممكن تجيب درجه كويسه افضل من غيرك .\n\nاضافات :\nمن الاخير اقولك اذا حصلته لحاله لا تنزل عنده نصيحه , قبل لا اسجل عنده دخلت الموقع وقريت عنه حصلت الاغلبيه مب عاجبهم لكن قلت بنفسي ان ممكن تغيير لان الاغلب كانت ردود قديمه , لا تغلط نفس غلطي وتنزل عنده نصييييحه أأجل الكورس ولا نزل عنده غيره لو فيه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527697-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-ahmed/118623/25", "user": "Guest", "ts": 1610103895000, "tid": 118623, "pn": 25}}]}', 1610103895000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abubakermt-ics253', 'stk-abubakermt', 'ICS 253', 'doc', '{"docs": [{"id": "stk-dr-f118623", "n": "Dr. Adel Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS253 Term222\n\nالتحضير: ورقة يمررها لكم و توقع عليها، متساهل جدا من ناحية التأخير لدرجة اذكر ان في واحد جا قبل نهاية المحاضرة بخمس دقايق و حضر طبيعي.\n\nطريقة الشرح: يشرح من الكتاب و شرحه جيد و اغلب المفاهيم مفهومة و مستعد يعيد شرح اي جزئية اذا ما فهمت\n\nالكويزات: كان الكورد اللي هو المحمدي يحطها و الصدق أجرم فينا و نفس الكلام بالميد. الكويزات بالمادة ذي عليها 20% و المشكلة ما اخذنا الا 5 كويزات بس فلازم تذاكر كويس للكويزات و تعاملها معاملة المياجر.\n\nالصوت: واضح و مسموع للكل و لغته واضحة.\n\nالقريد النهائي: B+\n\nإضافات: الدكتور طيب و يرحب بالاسئلة على تيمز، لازم يكون معاك الكتاب او نسخة الكترونية لان كل يوم تقريبا بيخليكم تتمرنون. الدكتور يحب يمزح مع الطلاب و ذا يعطي جو بالفصل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536692-ics253", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-ahmed/118623/26", "user": "AbubakerMT", "ts": 1684169016000, "tid": 118623, "pn": 26}}]}', 1684169016000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
